SELECT itinerary_json
FROM ai_itineraries
WHERE destination = '{{ $json.body.destination }}'
AND days = {{ $json.body.days }}
AND budget_range = '{{ $json.body.budget_range }}'
AND season = '{{ $json.body.season }}'
AND people = {{ $json.body.people }}
AND expires_at > NOW();

SELECT hotel_json
FROM hotels_cache
WHERE city = '{{ $("Webhook").item.json.body.destination }}';

