parameters.jsCode:
const text = $json.candidates[0].content.parts[0].text;

// Remove markdown fences if Gemini returned them
const cleaned = text
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

return {
  json: JSON.parse(cleaned)
};

const body = $('Webhook').first().json.body;

// Collect all hotels returned by PostgreSQL
const hotels = $input.all().map(item => ({
  name: item.json.hotel_json.name,
  rating: item.json.hotel_json.rating,
  price_per_night_inr: item.json.hotel_json.price_per_night_inr,
  address: item.json.hotel_json.address
}));

// Choose model
let model = "gemini-3.5-flash";

const destination = body.destination || "";
const days = Number(body.days || 1);
const budget = (body.budget_range || "").toLowerCase();
const constraints = body.constraints || [];

const isComplex =
  days >= 8 ||
  destination.includes(",") ||
  constraints.length >= 5 ||
  budget === "luxury";

if (isComplex) {
  model = "gemini-2.5-pro";
}

// Build prompt
const prompt = `
You are an expert travel planner.

Trip Details
Destination: ${body.destination}
Days: ${body.days}
Budget: ${body.budget_range}
Season: ${body.season}
People: ${body.people}

Available Cached Hotels:
${JSON.stringify(hotels, null, 2)}

Instructions:

1. Prefer selecting a hotel from the cached list.
2. If none of the cached hotels are suitable, recommend a better hotel using your own knowledge.
3. Mention whether the hotel source is "cache" or "gemini".
4. Generate a practical day-wise itinerary.
5. Keep travel times realistic.
6. Recommend famous local food.
7. Estimate daily and total cost.
8. Return ONLY valid JSON.
9. No markdown.
10. No explanation.

Return JSON ONLY in this format:

{
  "trip_details":{
    "destination":"",
    "days":0,
    "budget":"",
    "season":"",
    "people":0
  },
  "hotel":{
    "name":"",
    "rating":0,
    "price_per_night_inr":0,
    "address":"",
    "source":"cache"
  },
  "estimated_total_cost_inr":0,
  "itinerary":[
    {
      "day":1,
      "theme":"",
      "activities":[
        {
          "time":"",
          "activity":"",
          "description":""
        }
      ],
      "food":{
        "breakfast":"",
        "lunch":"",
        "dinner":""
      },
      "transport":"",
      "estimated_day_cost_inr":0
    }
  ],
  "travel_tips":[],
  "packing_tips":[]
}
`;

return [
  {
    json: {
      model,
      prompt
    }
  }
];
